import{CHARACTERS,PRESETS}from'./characters.js';import{ARENA,createPrototypeState,getActionHint,getComboRank,getFormation,getResults,getWeakPoint,stepPrototype,tapPrototype}from'./physics.js?v=v32-skills-1';
const KEY='qunxiong-world-blackwind-prototype-v3-2',canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),setup=document.querySelector('[data-setup]'),battle=document.querySelector('[data-battle]'),roster=document.querySelector('[data-roster]'),teamBox=document.querySelector('[data-team]'),presets=document.querySelector('[data-presets]'),result=document.querySelector('.result');canvas.width=ARENA.width;canvas.height=ARENA.height;let chosen=[...PRESETS.burst.team],state=null,last=0,raf=0,frames=0,fpsIn=0,hudIn=0;
const ui={time:document.querySelector('[data-time]'),combo:document.querySelector('[data-combo]'),rank:document.querySelector('[data-rank]'),power:document.querySelector('[data-power]'),powerLabel:document.querySelector('[data-power-label]'),break:document.querySelector('[data-break]'),breakLabel:document.querySelector('[data-break-label]'),hint:document.querySelector('[data-hint]'),banner:document.querySelector('[data-skill-banner]'),teamName:document.querySelector('[data-team-name]')};
function setupUI(){presets.innerHTML=Object.entries(PRESETS).map(([id,p])=>`<button data-preset="${id}">${p.name}</button>`).join('');roster.innerHTML=Object.entries(CHARACTERS).map(([id,c])=>`<button class="card" data-character="${id}"><b style="color:${c.color}">${c.name}</b><span>${c.role}・${c.passive}</span><small>${c.skill}</small></button>`).join('');drawChoice();}
function drawChoice(){teamBox.innerHTML=chosen.map((id,i)=>`<div class="slot"><small>${i?'主戰':'隊長'}</small><b style="color:${CHARACTERS[id].color}">${CHARACTERS[id].name}</b><small>${CHARACTERS[id].synergy}</small></div>`).join('');roster.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',chosen.includes(b.dataset.character)));}
presets.onclick=e=>{const id=e.target.dataset.preset;if(!id)return;chosen=[...PRESETS[id].team];drawChoice();presets.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.preset===id));};roster.onclick=e=>{const b=e.target.closest('[data-character]');if(!b)return;const id=b.dataset.character,at=chosen.indexOf(id);if(at>=0)chosen.splice(at,1);else if(chosen.length<3)chosen.push(id);else chosen[2]=id;drawChoice();};
function start(){if(chosen.length!==3)return;state=createPrototypeState(chosen);setup.hidden=true;battle.hidden=false;result.className='result';result.innerHTML='';ui.teamName.textContent=chosen.map(id=>CHARACTERS[id].name).join('・');last=0;}
function back(){state=null;battle.hidden=true;setup.hidden=false;result.className='result';}
function hero(f,i,alpha=1){const c=CHARACTERS[f.id];ctx.save();ctx.globalAlpha=alpha;ctx.translate(f.x,f.y);ctx.fillStyle='#02081299';ctx.beginPath();ctx.ellipse(0,20,20,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#182536';ctx.strokeStyle=c.color;ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,2,18,23,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#ecc39c';ctx.beginPath();ctx.arc(0,-9,10,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(-13,-8);ctx.lineTo(0,-28);ctx.lineTo(14,-8);ctx.lineTo(6,-15);ctx.closePath();ctx.fill();ctx.restore();}
function bg(){const g=ctx.createLinearGradient(0,0,0,520);g.addColorStop(0,'#30162d');g.addColorStop(.55,'#101b25');g.addColorStop(1,'#060d14');ctx.fillStyle=g;ctx.fillRect(0,0,360,520);ctx.strokeStyle='#b98c5938';for(let i=0;i<8;i++){ctx.beginPath();ctx.moveTo(i*52-20,520);ctx.lineTo(i*52+65,40);ctx.stroke();}ctx.fillStyle='#24364d';ctx.fillRect(45,468,115,17);ctx.fillRect(200,468,115,17);}
function boss(){const b=state.boss,wp=getWeakPoint(state);ctx.save();ctx.translate(b.x+b.recoilX,b.y);if(b.flash)ctx.filter='brightness(2.5)';ctx.fillStyle='#252b3a';ctx.strokeStyle='#d7b65b';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-42,38);ctx.lineTo(-34,-16);ctx.lineTo(-18,-48);ctx.lineTo(0,-58);ctx.lineTo(24,-43);ctx.lineTo(43,38);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ddb58e';ctx.beginPath();ctx.arc(0,-18,17,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ee574e';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(20,-8);ctx.lineTo(55,30);ctx.stroke();ctx.restore();ctx.strokeStyle='#fff36b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(wp.x,wp.y,12,0,Math.PI*2);ctx.stroke();if(state.shield){ctx.strokeStyle='#f2de8b';ctx.lineWidth=5;ctx.beginPath();ctx.arc(state.core.x,state.core.y,38,0,Math.PI*2);ctx.stroke();}}
function skillVfx(){const k=state.skill;if(!k)return;const c=CHARACTERS[k.id],p=k.elapsed/k.duration;ctx.save();ctx.globalCompositeOperation='lighter';ctx.strokeStyle=c.color;ctx.fillStyle=c.color;ctx.shadowColor=c.color;ctx.shadowBlur=16;if(k.motion==='slash'){ctx.lineWidth=12;ctx.beginPath();ctx.arc(state.boss.x,state.boss.y,70,-2.8+p*2,.5+p*2);ctx.stroke();}else if(k.motion==='smash'){ctx.lineWidth=9;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(state.boss.x,state.boss.y,25+p*65+i*10,0,Math.PI*2);ctx.stroke();}}else if(k.motion==='support'){ctx.globalAlpha=.45;ctx.beginPath();ctx.arc(180,300,35+p*130,0,Math.PI*2);ctx.fill();}else if(k.motion==='ricochet'){ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(k.x,k.y);ctx.lineTo(k.x<180?330:30,k.y-45);ctx.stroke();}else if(k.motion==='burn'){ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(k.x-55,k.y+30);ctx.lineTo(k.x,k.y);ctx.stroke();for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(k.x-15+i*8,k.y+20,4+i,0,Math.PI*2);ctx.fill();}}else if(k.motion==='pierce'){ctx.lineWidth=6;ctx.setLineDash([16,8]);ctx.beginPath();ctx.moveTo(20,k.y);ctx.lineTo(340,k.y);ctx.stroke();}else if(k.motion==='storm'){ctx.lineWidth=6;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(120+i*40,10);ctx.lineTo(150+i*15,state.boss.y);ctx.lineTo(130+i*30,state.boss.y+50);ctx.stroke();}}else if(k.motion==='guard'){ctx.lineWidth=9;ctx.beginPath();ctx.arc(180,300,70,Math.PI,Math.PI*2);ctx.stroke();}else if(k.motion==='hunt'){ctx.lineWidth=8;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(state.boss.x-70+i*25,state.boss.y+60);ctx.lineTo(state.boss.x-25+i*25,state.boss.y-60);ctx.stroke();}}else{ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(k.x-65,k.y);ctx.lineTo(k.x,k.y);ctx.stroke();}ctx.restore();hero({x:k.x,y:k.y,id:k.id},0);}
function events(){for(const e of state.events){const a=Math.max(0,Math.min(1,e.life/.7));ctx.save();ctx.globalAlpha=a;ctx.textAlign='center';ctx.fillStyle=e.color||'#fff';ctx.strokeStyle='#081018';ctx.lineWidth=5;ctx.font=`900 ${['break','skill-intro','counter'].includes(e.type)?23:18}px sans-serif`;ctx.strokeText(e.text||'',e.x,e.y);ctx.fillText(e.text||'',e.x,e.y);ctx.restore();}}
function render(){if(!state)return;ctx.clearRect(0,0,360,520);bg();boss();const form=getFormation(state);ctx.lineWidth=4;form.forEach((f,i)=>{const h=state.history[Math.min(i*5,state.history.length-1)];if(h){ctx.strokeStyle=CHARACTERS[f.id].color+'88';ctx.beginPath();ctx.moveTo(h.x,h.y);ctx.lineTo(f.x,f.y);ctx.stroke();}hero(f,i,i?0.9:1);});skillVfx();events();}
function sync(){if(!state)return;ui.time.textContent=state.timeLeft.toFixed(1);ui.combo.textContent=`${state.combo} HIT`;ui.rank.textContent=getComboRank(state.combo);ui.power.style.width=`${state.power}%`;ui.powerLabel.textContent=state.powerTier?`${CHARACTERS[state.team[0]].synergy} READY`:'蓄力中';ui.break.style.width=`${state.breakGauge}%`;ui.breakLabel.textContent=state.breakIn?`BREAK ${state.breakIn.toFixed(1)}s`:`弱點：${['左','上','右'][state.boss.weakSide]}`;ui.hint.textContent=getActionHint(state);ui.banner.textContent=state.skill?(state.skill.ultimate?CHARACTERS[state.skill.id].ultimate:CHARACTERS[state.skill.id].skill):state.boss.move?.name||'';if(state.complete&&!result.classList.contains('show')){const r=getResults(state);result.innerHTML=`<h2>Prototype Complete</h2><p>${r.team.map(id=>CHARACTERS[id].name).join('・')}</p><dl><dt>最高 Combo</dt><dd>${r.highestCombo}</dd><dt>傷害</dt><dd>${r.damage}</dd><dt>BREAK</dt><dd>${r.breaks}</dd><dt>技能／Ultimate</dt><dd>${r.skills}／${r.ultimates}</dd><dt>Perfect</dt><dd>${r.perfectFlips+r.perfectCounters}</dd><dt>治療</dt><dd>${r.healing}</dd><dt>撞牆</dt><dd>${r.wallHits}</dd><dt>剩餘 HP</dt><dd>${r.hp}</dd></dl><button type="button">同隊再戰</button>`;result.classList.add('show');result.querySelector('button').onclick=start;try{localStorage.setItem(KEY,JSON.stringify({last:r,team:chosen}));}catch{}}}
function frame(now){const dt=last?Math.min(.034,(now-last)/1000):.016;last=now;if(state)stepPrototype(state,dt);render();hudIn-=dt;if(hudIn<=0){sync();hudIn=.08;}frames++;fpsIn+=dt;if(fpsIn>=1){document.body.dataset.fps=String(Math.round(frames/fpsIn));frames=0;fpsIn=0;}raf=requestAnimationFrame(frame);}canvas.addEventListener(window.PointerEvent?'pointerdown':'touchstart',e=>{e.preventDefault();if(state)tapPrototype(state);},{passive:false});document.querySelector('[data-start]').onclick=start;document.querySelector('[data-back]').onclick=back;setupUI();requestAnimationFrame(frame);
